# ---------------------------------------------------------------------------
# Assemble full catalog
# ---------------------------------------------------------------------------

def get_curated_catalog() -> list[dict]:
    """Return the full curated whiskey catalog as a list of dicts.

    Each dict has keys: name, distillery, region, age_statement, abv,
    bottling_year, price_eur, is_limited, rarity, notes.
    """
    catalog: list[dict] = []
    catalog.extend(_japanese_whisky())
    catalog.extend(_scotch_single_malt())
    catalog.extend(_bourbon_american())
    catalog.extend(_irish_whiskey())
    catalog.extend(_limited_special_editions())
    catalog.extend(_vintage_closed_distilleries())
    catalog.extend(_additional_whisky())
    catalog.extend(_expanded_whisky_batch1())
    catalog.extend(_expanded_whisky_batch2())
    catalog.extend(_expanded_whisky_batch3())
    catalog.extend(_expanded_whisky_batch4())
    catalog.extend(_expanded_whisky_batch5())
    catalog.extend(_expanded_whisky_batch6())
    catalog.extend(_variant_expansion())
    catalog.extend(_expanded_whisky_batch7())
    catalog.extend(_expanded_whisky_batch8())
    catalog.extend(_expanded_whisky_batch9())
    # Deduplicate by ('distillery', 'name') (keep first occurrence)
    _seen: set = set()
    _deduped: list = []
    for item in catalog:
        _key = (item["distillery"], item["name"])
        if _key not in _seen:
            _seen.add(_key)
            _deduped.append(item)
    return _deduped


